ext('c12_eng_ch20',[
C("🐍","कविता की स्थिति और पृष्ठभूमि",["कवि: डी. एच. लॉरेंस","स्थान: सिसिली","गर्मी का दिन","पानी के कुंड पर साँप"],"स्नेक कविता डी एच लॉरेंस ने लिखी है। इसमें कवि गर्मी के एक तपते दिन सिसिली में अपने घर के पास पानी के कुंड पर जाता है। वहाँ वह एक सुनहरे-भूरे साँप को पहले से पानी पीते देखता है। कवि वहीं रुककर इंतज़ार करता है कि साँप पहले पी ले। यह कविता एक साधारण घटना से शुरू होती है, पर जल्द ही कवि के मन में चल रहे विचारों और भावनाओं की गहराई में पहुँच जाती है।"),
Q("कविता का दृश्य कहाँ और किस मौसम का है?","सिसिली में, गर्म दिन में, पानी के कुंड के पास","दृश्य याद कीजिए... यह तपती गर्मी का दिन है। कवि पानी लेने कुंड पर आता है, जहाँ एक साँप पहले से पानी पी रहा है। जगह है सिसिली, जो इटली का द्वीप है। गर्मी के कारण साँप भी ठंडक की खोज में पानी के पास आया था।"),
C("👀","साँप का वर्णन",["सुनहरा-भूरा रंग","धीरे-धीरे पीता हुआ","जीभ बाहर निकालता","शांत और निश्चिंत"],"कवि ने साँप का बड़ा सुंदर चित्र खींचा है। वह सुनहरे-भूरे रंग का है और पीते समय बिलकुल शांत और निश्चिंत है। जैसे कोई मेहमान आराम से पानी पी रहा हो। वह अपनी जीभ बार-बार बाहर निकालता है और फिर सोच में डूबा हुआ-सा लगता है। इस वर्णन से पाठक को साँप से डर कम और उसके प्रति आकर्षण ज़्यादा महसूस होता है। कवि उसे एक भूमिगत जगत के राजा की तरह देखता है।"),
Q("कवि साँप को अपना मेहमान क्यों समझता है?","क्योंकि साँप पहले से पानी के कुंड पर था और कवि बाद में आया","सोचिए... कवि को लगता है कि साँप पहले आया है, इसलिए अधिकार उसका है। कवि क़तार में अपनी बारी का इंतज़ार करता है। वह साँप का सम्मान करता है, भले ही उसे डर भी लगता है। यही विनम्रता कविता को ख़ास बनाती है।"),
C("⚔️","कवि के भीतर दो आवाज़ें",["सामाजिक शिक्षा की आवाज़","स्वाभाविक सम्मान की आवाज़","डर बनाम आकर्षण","तर्क बनाम भावना"],"कविता का मुख्य तनाव कवि के मन के अंदर है। एक आवाज़ कहती है, सिसिली में सुनहरे साँप ज़हरीले होते हैं, इसलिए इसे मार दो। यह समाज से सीखी हुई आवाज़ है। दूसरी आवाज़ कहती है, यह साँप मेरा मेहमान है, इसका आदर करो। यह आवाज़ भीतर की सच्ची संवेदना है। कवि इन दोनों के बीच खिंचता रहता है और यही द्वंद्व कविता का हृदय है।"),
Q("कवि के मन में कौन-से दो भाव टकराते हैं?","डर और समाज की सीख बनाम साँप के प्रति सम्मान और आकर्षण","दो पक्ष सोचिए... एक ओर समाज की सिखाई बात कि ज़हरीले साँप को मार दो। दूसरी ओर सहज भावना कि यह एक सुंदर प्राणी है और इसका सम्मान करो। यह मन की लड़ाई ही कविता का सबसे महत्वपूर्ण भाग है।"),
C("🪵","लकड़ी फेंकने की घटना",["साँप का लौटकर जाना","कवि का अचानक ग़ुस्सा","लकड़ी का टुकड़ा फेंकना","साँप का तेज़ी से भागना"],"जब साँप पीकर अपने बिल में वापस जाने लगा, तो उसका आधा शरीर अंदर और आधा बाहर था। उसी क्षण कवि के भीतर की डरी हुई आवाज़ हावी हो गई और उसने एक लकड़ी का टुकड़ा साँप की ओर फेंक दिया। साँप चौंककर बहुत तेज़ी से बिल में घुस गया। कवि को तुरंत पछतावा हुआ। उसे लगा कि उसने कुछ बहुत नीच और मामूली काम कर दिया है।"),
Q("कवि को लकड़ी फेंकने के बाद कैसा लगा?","पछतावा; उसे अपना काम नीच और ओछा लगा","अंत का भाव याद कीजिए... लकड़ी फेंकते ही कवि को अपने काम पर शर्मिंदगी हुई। उसे लगा जैसे उसने एक महान अतिथि का अपमान कर दिया हो। यह पछतावा कविता की सबसे गहरी भावना है।"),
C("👑","साँप का प्रतीक और सम्राट का बिंब",["राजा जैसा, गरिमा वाला","भूमिगत जगत का राजा","प्रकृति का प्रतीक","अपमानित सम्राट"],"कवि साँप को एक निर्वासित राजा की तरह देखता है, जो ज़मीन के भीतर के लोक से आया है। यह साँप प्रकृति के उस हिस्से का प्रतीक है जिससे हम डरते हैं या जिसे समझ नहीं पाते। कवि पछताता है कि उसने एक राजसी प्राणी का अपमान किया। लॉरेंस के लिए यह पछतावा बताता है कि हम समाज की सिखाई बातों के कारण प्रकृति के सच्चे सौंदर्य को पहचान नहीं पाते।"),
Q("साँप किसका प्रतीक है?","प्रकृति और जीवन के रहस्यमय, गरिमामय पक्ष का","सोचिए... साँप को कवि ने राजा जैसा बताया है। वह प्रकृति की उस शक्ति का प्रतीक है जिसे हम डर के कारण नहीं समझ पाते। कविता कहती है कि हर प्राणी का सम्मान होना चाहिए।"),
C("🎭","भाषा और शैली",["मुक्त छंद","बिंब और उपमा","संवादात्मक लहजा","पुनरावृत्ति"],"कविता मुक्त छंद में लिखी गई है, यानी इसमें तुक या निश्चित मात्रा नहीं है। लेखक का लहजा बातचीत जैसा है, जैसे कोई अपनी कहानी सुना रहा हो। बिंब बहुत सजीव हैं, जैसे गर्मी का दिन, पानी का कुंड और साँप की जीभ। कुछ शब्दों और वाक्यों की पुनरावृत्ति से भाव गहरा होता है। छोटी-बड़ी पंक्तियाँ साँप की धीमी चाल का अहसास कराती हैं।"),
Q("स्नेक कविता किस छंद में है?","मुक्त छंद (free verse)","याद कीजिए... इस कविता में कोई निश्चित तुक या लय नहीं है। पंक्तियाँ छोटी-बड़ी हैं और बातचीत की तरह बहती हैं। इसे मुक्त छंद कहते हैं।"),
C("🧭","कविता का संदेश और सीख",["हर जीव का सम्मान","भय पर समझ की जीत","सहज सहानुभूति पर भरोसा","पछतावे से सीखना"],"कविता हमें सिखाती है कि हर जीव को सम्मान और स्थान मिलना चाहिए। डर के कारण हम कई बार ग़लत कदम उठा लेते हैं। हमारी भीतरी सहज संवेदना अकसर सही होती है और हमें उसकी बात सुननी चाहिए। ग़लती हो जाए तो पछताना और उससे सीखना ही इंसानियत है। पशु-पक्षी और प्रकृति के प्रति करुणा हमें बेहतर इंसान बनाती है।"),
C("✍️","उत्तर लिखने के सुझाव",["घटना का क्रम","भावनाओं का द्वंद्व","प्रतीक और सीख","अपने शब्दों में निष्कर्ष"],"इस कविता पर उत्तर लिखते समय घटना को क्रम से लिखिए, यानी कुंड पर पहुँचना, साँप को देखना, मन का द्वंद्व, लकड़ी फेंकना और पछतावा। फिर साँप के प्रतीक का अर्थ समझाइए। अपने शब्दों में निष्कर्ष लिखिए कि कवि ने हमें प्रकृति के प्रति आदर और सहज संवेदना की सीख दी है। कविता की पंक्तियाँ ज्यों की त्यों दोहराने के बजाय भाव अपने शब्दों में लिखिए।"),
],7)
